// === Tab: mySketch ===
let boids = []
let amount = 6;

function setup() {
 createCanvas(666, 666,WEBGL)

 for(var i=0;i<amount;i++){
  boids.push(new boid())
 }

}

function draw() {
 background(122)
 scale(0.75);
 translate(-width/2,-height/2)



 for(var v=0;v<boids.length;v++){

    boids[v].move()
    boids[v].show()



   let distance = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),boids[v].x,boids[v].y)

   if (distance<20){
      boids[v].c = color('red')}
   else {boids[v].c = color('black')}


   var spts = boids.slice(0,boids.length-1);

   var epts = boids.slice(1);

	 for(let i = 0; i < spts.length; i++){
   strokeWeight(0.5);
	 stroke('white');
	 line(spts[i].x,spts[i].y,spts[i].z,epts[i].x,epts[i].y,epts[i].z);}

 }

}








class boid{

  constructor(x=random(width),y=random(height)){
    this.x = x
    this.y = y
    this.z = random(-100,100)
    this.vx = random(0.2,1.1)
    this.vy = random(0.2,1.1)
    this.vz = random(0.2,1.1)
    this.size = random(12,22)
    this.c = color('black')
  }

  move(){

    this.x += this.vx 
    this.y += this.vy
    this.z += this.vz

    if(this.x < 45 || this.x > width-45){
    this.vx *= -1
    }

    if(this.y < 45 || this.y > height-45){
    this.vy *= -1
    }

    if(this.z < -300 || this.z > 300){
    this.vz *= -1
    }

  }

  show(){

    push();

    fill(this.c,100)



    translate(this.x,this.y,this.z)

    rotateY(-frameCount*.02)
    sphere(this.size,8,8)



    pop()

  }

}


function mousePressed(){

   for(var v=0;v<boids.length;v++){

   var distance = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),boids[v].x,boids[v].y)

   if (distance<20){
      boids.splice(v,1)}
   }


}


function mouseDragged(){

	boids.push(new boid((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));


}

